#!/usr/bin/env bash
# Question 4: DaemonSet ${Q4_DS} on edge nodes. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl -n "${Q4_NS}" delete daemonset "${Q4_DS}" --ignore-not-found --wait=true >/dev/null
kubectl label nodes --all node-type- >/dev/null 2>&1 || true
: "${Q4_NS}" "${Q4_STS}" "${Q4_DS}"
